"use client"

import { useCallback, useRef, useState, useSyncExternalStore, type ReactNode, type RefObject } from "react"
import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react"

import { Button } from "@/components/ui/button"

type TabsScrollLabels = {
  /** Names of the pointer-only scroll buttons. They are hidden from screen readers, which reach every tab by arrow keys. */
  left: string
  right: string
}

const tabsScrollLabels: TabsScrollLabels = { left: "Scroll tabs left", right: "Scroll tabs right" }

type Edges = { left: boolean; right: boolean }

// Physical edges, not logical ones: scrollLeft is negative under rtl in every current engine, and the fades and
// buttons are placed physically, so reading both sides from the absolute offset covers both directions.
function readEdges(element: HTMLElement): Edges {
  const max = element.scrollWidth - element.clientWidth
  if (max <= 1) return { left: false, right: false }
  const offset = Math.abs(element.scrollLeft)
  const fromStart = offset > 1
  const toEnd = offset < max - 1
  const rtl = getComputedStyle(element).direction === "rtl"
  return rtl ? { left: toEnd, right: fromStart } : { left: fromStart, right: toEnd }
}

function prefersReducedMotion() {
  return typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches
}

// Scrolls only the list, never the page or a scrolling ancestor, so a tab an agent selects off screen doesn't
// move the page. The list's scroll padding is the fade's width, so the tab lands clear of it. The target is
// absolute, so a second call while a smooth scroll runs (focus and selection change together) lands in the same place.
function revealTab(list: HTMLElement, tab: HTMLElement, smooth: boolean) {
  if (list.scrollWidth - list.clientWidth <= 1) return
  const style = getComputedStyle(list)
  const bounds = list.getBoundingClientRect()
  const box = tab.getBoundingClientRect()
  const left = box.left - (bounds.left + (Number.parseFloat(style.scrollPaddingLeft) || 0))
  const right = box.right - (bounds.right - (Number.parseFloat(style.scrollPaddingRight) || 0))
  const rtl = style.direction === "rtl"
  // A tab wider than the clear space shows its start.
  const delta = left < 0 && right > 0 ? (rtl ? right : left) : left < 0 ? left : right > 0 ? right : 0
  if (Math.abs(delta) < 1) return
  list.scrollTo({ left: list.scrollLeft + delta, behavior: smooth && !prefersReducedMotion() ? "smooth" : "auto" })
}

function isTab(node: unknown): node is HTMLElement {
  return node instanceof HTMLElement && node.getAttribute("role") === "tab"
}

const noEdges: Edges = { left: false, right: false }

// The subscription also keeps the selected tab in view: on mount, after each resize (tabs change width as fonts load
// or labels change), on focus and on selection. Geometry is read only where layout is already clean (the resize
// observer, scroll events, an animation frame), never in the focus or key event: a list that fits does nothing on an
// arrow press, and one that scrolls reveals its tab in the next frame.
function createEdgesStore() {
  let edges = noEdges
  return {
    getSnapshot: () => edges,
    getServerSnapshot: () => noEdges,
    watch(element: HTMLElement | null, onChange: () => void) {
      if (!element) return () => {}
      let overflows = false
      let frame = 0
      let pending: { tab: HTMLElement; smooth: boolean } | null = null
      const update = () => {
        overflows = element.scrollWidth - element.clientWidth > 1
        const next = readEdges(element)
        if (next.left === edges.left && next.right === edges.right) return
        edges = next
        onChange()
      }
      const reveal = (tab: HTMLElement, smooth: boolean) => {
        if (!overflows) return
        pending = { tab, smooth: pending?.smooth === false ? false : smooth }
        if (frame) return
        frame = requestAnimationFrame(() => {
          frame = 0
          const target = pending
          pending = null
          if (target?.tab.isConnected) revealTab(element, target.tab, target.smooth)
        })
      }
      const revealSelected = () => {
        const selected = element.querySelector<HTMLElement>('[role="tab"][aria-selected="true"]')
        if (selected) revealTab(element, selected, false)
      }
      const observer =
        typeof ResizeObserver === "function"
          ? new ResizeObserver(() => {
              update()
              revealSelected()
            })
          : undefined
      observer?.observe(element)
      for (const child of element.children) observer?.observe(child)
      element.addEventListener("scroll", update, { passive: true })
      update()

      const onFocus = (event: FocusEvent) => {
        if (isTab(event.target)) reveal(event.target, true)
      }
      const selection =
        typeof MutationObserver === "function"
          ? new MutationObserver((records) => {
              for (const record of records) {
                if (isTab(record.target) && record.target.getAttribute("aria-selected") === "true") {
                  reveal(record.target, true)
                }
              }
            })
          : undefined
      selection?.observe(element, { attributes: true, attributeFilter: ["aria-selected"], subtree: true })
      element.addEventListener("focusin", onFocus)
      revealSelected()
      return () => {
        cancelAnimationFrame(frame)
        observer?.disconnect()
        selection?.disconnect()
        element.removeEventListener("scroll", update)
        element.removeEventListener("focusin", onFocus)
      }
    },
  }
}

function useScrollEdges() {
  const ref = useRef<HTMLDivElement>(null)
  const [store] = useState(createEdgesStore)
  const subscribe = useCallback((onChange: () => void) => store.watch(ref.current, onChange), [store])
  const edges = useSyncExternalStore(subscribe, store.getSnapshot, store.getServerSnapshot)

  const scroll = (direction: -1 | 1) => {
    const element = ref.current
    if (!element) return
    element.scrollBy({
      left: direction * element.clientWidth * 0.8,
      behavior: prefersReducedMotion() ? "auto" : "smooth",
    })
  }

  return { ref, edges, scroll }
}

type ScrollButtonProps = { side: "left" | "right"; label: string; onScroll: () => void }

// Pointer-only, so aria-hidden and out of the tab order; agents select tabs on the tablist itself.
function ScrollButton({ side, label, onScroll }: ScrollButtonProps) {
  return (
    <span
      data-slot="tabs-scroll-button"
      data-side={side}
      className="absolute inset-y-0 hidden items-center rounded-control bg-muted data-[side=left]:left-0 data-[side=right]:right-0 group-data-overflow-left/tabs-scroll:data-[side=left]:pointer-fine:flex group-data-overflow-right/tabs-scroll:data-[side=right]:pointer-fine:flex"
    >
      <Button
        variant="ghost"
        size="icon"
        aria-label={label}
        aria-hidden="true"
        tabIndex={-1}
        data-agent-hidden=""
        onClick={onScroll}
      >
        {side === "left" ? <ChevronLeftIcon /> : <ChevronRightIcon />}
      </Button>
    </span>
  )
}

type TabsScrollProps = {
  labels?: Partial<TabsScrollLabels>
  children: (ref: RefObject<HTMLDivElement | null>) => ReactNode
}

function TabsScroll({ labels: labelOverrides, children }: TabsScrollProps) {
  const labels = { ...tabsScrollLabels, ...labelOverrides }
  const { ref, edges, scroll } = useScrollEdges()
  return (
    <div
      data-slot="tabs-scroll"
      data-overflow-left={edges.left ? "" : undefined}
      data-overflow-right={edges.right ? "" : undefined}
      className="group/tabs-scroll relative flex max-w-full min-w-0 has-data-[orientation=vertical]:contents"
    >
      {children(ref)}
      <ScrollButton side="left" label={labels.left} onScroll={() => scroll(-1)} />
      <ScrollButton side="right" label={labels.right} onScroll={() => scroll(1)} />
    </div>
  )
}

export { readEdges, revealTab, TabsScroll, tabsScrollLabels }
export type { TabsScrollLabels }

"use client"

import {
  Tabs as TabsPrimitive,
  TabsIndicator,
  TabsList as TabsListPrimitive,
  TabsPanel as TabsPanelPrimitive,
  TabsTab as TabsTabPrimitive,
  TabsTabIcon,
  createTabsController,
  type TabsController,
} from "@ui-sdk/react/tabs"
import { createContext, use, useState, type ComponentProps, type PointerEvent } from "react"

import { TabsScroll, type TabsScrollLabels } from "@/components/ui/tabs-scroll"
import { cn, cnState } from "@/lib/utils"

// Set only while activateOnPress is on: the controller a tab selects through on pointerdown.
const TabsPressContext = createContext<TabsController | null>(null)

type TabsProps<T extends string = string> = ComponentProps<typeof TabsPrimitive<T>> & {
  /**
   * Selects a tab as soon as a mouse or pen presses it, before release, like native tab bars. Touch still selects
   * on release, so scrolling a tab bar doesn't select. Keyboard and agents are unchanged. Off by default.
   */
  activateOnPress?: boolean
}

function Tabs<T extends string = string>({ className, activateOnPress = false, controller, ...props }: TabsProps<T>) {
  const [ownController] = useState(() => createTabsController<T>())
  const active = controller ?? ownController
  return (
    <TabsPressContext value={activateOnPress ? (active as TabsController) : null}>
      <TabsPrimitive<T>
        controller={active}
        className={cnState("flex flex-col gap-items data-[orientation=vertical]:flex-row", className)}
        {...props}
      />
    </TabsPressContext>
  )
}

const tabsListClassName =
  "relative inline-flex w-fit items-center rounded-control bg-muted p-control-inset text-muted-foreground data-[orientation=vertical]:flex-col data-[orientation=vertical]:items-stretch"

// A scrolling list clips on both axes, so a tab's focus ring drops its offset to fit inside the list's rim.
// The fades are masks over the list itself, so they work on any surface; each side's width is 0 until it overflows.
// The scroll padding is the fade's width, so a tab TabsScroll reveals lands clear of it.
const scrollClassName = [
  // oxlint-disable-next-line eskais/scroll-area -- a scrolling tab list hides its scrollbar on purpose: edge fades and scroll buttons stand for it
  "max-w-full overflow-x-auto overscroll-x-contain [--tabs-fade:2.5rem] scroll-px-(--tabs-fade) [scrollbar-width:none] [&::-webkit-scrollbar]:hidden [&_[data-slot=tabs-tab]]:focus-visible:ring-offset-0",
  "[--fade-left:0px] [--fade-right:0px] group-data-overflow-left/tabs-scroll:[--fade-left:var(--tabs-fade)] group-data-overflow-right/tabs-scroll:[--fade-right:var(--tabs-fade)]",
  "[mask-image:linear-gradient(to_right,transparent,black_var(--fade-left),black_calc(100%-var(--fade-right)),transparent)]",
].join(" ")

type TabsListProps = ComponentProps<typeof TabsListPrimitive> & {
  /**
   * `"auto"` (default) lets a horizontal list scroll when its tabs don't fit, with edge fades and, on fine pointers,
   * scroll buttons; the selected or focused tab scrolls into view clear of the fades. `false` keeps it a plain list
   * that never scrolls.
   */
  scrollable?: "auto" | false
  scrollLabels?: Partial<TabsScrollLabels>
}

function TabsList({ className, scrollable = "auto", scrollLabels, ...props }: TabsListProps) {
  if (scrollable === false) return <TabsListPrimitive className={cnState(tabsListClassName, className)} {...props} />
  return (
    <TabsScroll labels={scrollLabels}>
      {(ref) => (
        <TabsListPrimitive
          ref={ref}
          className={cnState(cn(tabsListClassName, scrollClassName), className)}
          {...props}
        />
      )}
    </TabsScroll>
  )
}

// A solid primary fill on muted, so the selected tab reads at 3:1 rather than as a faint tint.
function TabsTab({ className, onPointerDown, ...props }: ComponentProps<typeof TabsTabPrimitive>) {
  const pressController = use(TabsPressContext)
  // Selecting on press is allowed by WCAG 2.5.2 (Pointer Cancellation) because it's reversible: pressing another
  // tab undoes it. It goes through the controller, so onValueChange, cancel() and controlled values still apply.
  const selectOnPress = (event: PointerEvent<HTMLButtonElement>) => {
    onPointerDown?.(event)
    if (!pressController || event.defaultPrevented || event.button !== 0 || event.pointerType === "touch") return
    pressController.select(props.value, { reason: "item-press", event: event.nativeEvent })
  }
  return (
    <TabsTabPrimitive
      onPointerDown={selectOnPress}
      className={cnState(
        "touch-target inline-flex h-control-sm shrink-0 cursor-pointer items-center justify-center gap-inline rounded-control px-control-x text-sm font-medium whitespace-nowrap transition-colors outline-none select-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-muted data-disabled:cursor-not-allowed data-disabled:opacity-50 data-disabled:hover:text-muted-foreground data-selected:bg-primary data-selected:text-primary-foreground data-selected:hover:text-primary-foreground [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        className,
      )}
      {...props}
    />
  )
}

function TabsPanel({ className, ...props }: ComponentProps<typeof TabsPanelPrimitive>) {
  return (
    <TabsPanelPrimitive
      className={cnState(
        "flex-1 rounded-control outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        className,
      )}
      {...props}
    />
  )
}

export { createTabsController, Tabs, TabsIndicator, TabsList, TabsPanel, TabsTab, TabsTabIcon }
export type { TabsListProps, TabsProps }
